#!/bin/sh
# Regenerate the OpenAPI spec and the committed API client for THIS checkout, without touching the dev database or anyone else's files.
#
#   docker/backend/codegen.sh            # export the spec, run orval, show what changed under frontend/packages/core-api
#   docker/backend/codegen.sh --check    # same, then fail (exit 1) if the generated client differs from what is committed
#
# The spec is exported by a throwaway container that mounts this checkout and connects to YOUR private test database (migrated first),
# not the dev `erp` database; the client is generated by this checkout's own node_modules. Both read and write only inside this
# checkout (backend/storage/api-docs, frontend/packages/core-api/src/generated), so two worktrees never overwrite each other.
# Before staging anything it generated, read docs/architecture/pre-push-checks.md "Generated files": every change must trace to an API
# change in YOUR commits.
set -e
. "$(dirname "$0")/test-lib.sh"
erp_check_checkout || exit 64
DB=$(erp_db_name); erp_validate_db "$DB" || exit 64
erp_check_vendor || exit 65
erp_lock stack 7 -s "codegen on $DB (the Docker stack is being restarted)"
erp_lock "db-$DB" 6 -x "codegen on $DB (another run is using database $DB; set ERP_AGENT=<you> for your own)"
erp_ensure_db "$DB" || exit $?
DBENV="-e DB_CONNECTION=pgsql -e DB_HOST=postgres-test -e DB_PORT=5432 -e DB_DATABASE=$DB -e CACHE_STORE=array -e SESSION_DRIVER=array -e QUEUE_CONNECTION=sync -e TEST_DB_HOST=postgres-test -e TEST_DB_PORT=5432 -e TEST_DB_DATABASE=$DB"
ERP_RUN_OPTS="$DBENV" erp_run php artisan migrate --database=testing --force --no-interaction >/dev/null
ERP_RUN_OPTS="$DBENV" erp_run php artisan scramble:export --path=storage/api-docs/openapi.json 2>&1 | grep -v '^ Container'
[ -d "$ERP_ROOT/frontend/node_modules" ] || { erp_note "frontend/node_modules is missing in $ERP_ROOT (docker/dev/worktree.sh add copies it)."; exit 67; }
(cd "$ERP_ROOT/frontend" && npm run codegen 6>&- 7>&-) >/dev/null
erp_note "generated files that differ from the commit:"
git -C "$ERP_ROOT" status --short -- frontend/packages/core-api | sed 's/^/  /' >&2
if [ "$1" = "--check" ]; then
  git -C "$ERP_ROOT" diff --quiet -- frontend/packages/core-api && [ -z "$(git -C "$ERP_ROOT" ls-files --others --exclude-standard -- frontend/packages/core-api)" ] \
    && { erp_note "client matches the commit."; exit 0; }
  erp_note "client DIFFERS from the commit."; exit 1
fi
